#     def __init__(self, x):
#         self.val = x
#         self.left = None
#         self.right = None

class Solution:
    indexes = {}
    def buildTree(self, inorder: List[int], postorder: List[int]) -> TreeNode:
        def build(inorder, postorder, i1, i2, p1, p2):
            if i1 > i2 or p1 > p2:
                return None
            root_val = postorder[p2]
            pos = self.indexes[root_val]
            root = TreeNode(root_val)
            root.left = None if pos == i1 else build(inorder, postorder, i1, pos - 1, p1, p1 - i1 + pos - 1)
            root.right = None if pos == i2 else build(inorder, postorder, pos + 1, i2, p1 - i1 + pos, p2 - 1)
            return root
        n = len(inorder)
        for i in range(n):
            self.indexes[inorder[i]] = i
        return build(inorder, postorder, 0, n - 1, 0, n - 1)

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
class Solution {
    private Map<Integer, Integer> indexes = new HashMap<>();

    public TreeNode buildTree(int[] inorder, int[] postorder) {
        int n = inorder.length;
        for (int i = 0; i < n; ++i) {
            indexes.put(inorder[i], i);
        }
        return build(inorder, postorder, 0, inorder.length - 1, 0, postorder.length - 1);
    }

    private TreeNode build(int[] inorder, int[] postorder, int i1, int i2, int p1, int p2) {
        if (i1 > i2 || p1 > p2) return null;
        int rootVal = postorder[p2];
        int pos = indexes.get(rootVal);
        TreeNode root = new TreeNode(rootVal);
        root.left = pos == i1 ? null : build(inorder, postorder, i1, pos - 1, p1, p1 - i1 + pos - 1);
        root.right = pos == i2 ? null : build(inorder, postorder, pos + 1, i2, p1 - i1 + pos, p2 - 1);
        return root;
    }
}

class Solution {
public:
    TreeNode *buildTree(vector<int> &inorder, vector<int> &postorder) {
        return buildTree(inorder, 0, inorder.size() - 1, postorder, 0, postorder.size() - 1);
    }
    TreeNode *buildTree(vector<int> &inorder, int iLeft, int iRight, vector<int> &postorder, int pLeft, int pRight) {
        if (iLeft > iRight || pLeft > pRight) return NULL;
        TreeNode *cur = new TreeNode(postorder[pRight]);
        int i = 0;
        for (i = iLeft; i < inorder.size(); ++i) {
            if (inorder[i] == cur->val)
                break;
        }
        cur->left = buildTree(inorder, iLeft, i - 1, postorder, pLeft, pLeft + i - iLeft - 1);
        cur->right = buildTree(inorder, i + 1, iRight, postorder, pLeft + i - iLeft, pRight - 1);
        return cur;
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
       // Helper function to recursively build a binary tree from given preorder and inorder traversals
TreeNode* treeBuilt(vector<int>& postorder, vector<int>& inorder, int& postIndex, int inOrderStart, int inOrderEnd, map<int, int>& mp) {
    // Base cases: check if the subtree is empty
    if (postIndex < 0 || inOrderStart > inOrderEnd)
        return NULL;

    // Create a new TreeNode with the current element from the preorder traversal
    int element = postorder[postIndex--];
    TreeNode* root = new TreeNode(element);

    // Find the position of the current element in the inorder traversal
    int position = mp[element];

        // Recursively build the right subtree with elements after the current element in inorder traversal
    root->right = treeBuilt(postorder, inorder, postIndex, position + 1, inOrderEnd, mp);

    // Recursively build the left subtree with elements before the current element in inorder traversal
    root->left = treeBuilt(postorder, inorder, postIndex, inOrderStart, position - 1, mp);



    // Return the current root of the subtree
    return root;
}

public:
    TreeNode* buildTree(vector<int>& inorder, vector<int>& postorder) {

    int postIndex = postorder.size() - 1;
    int inOrderStart = 0;
    int inOrderEnd = inorder.size() - 1;
    map<int, int> mp;

    // Create a map to store the positions of elements in the inorder traversal
    for (int i = 0; i < inorder.size(); i++) {
        mp[inorder[i]] = i;
    }

    // Call the helper function to build the tree and return the root
    return treeBuilt(postorder, inorder, postIndex, inOrderStart, inOrderEnd, mp);

    }
};

class Solution {
public:
    TreeNode* build(vector<int>& in, int x, int y, vector<int>& po, int a, int b) {
        if (x > y or a > b) {
            return nullptr;
        }
        TreeNode *node = new TreeNode(po[b]);
        int inStart = x;  
        while(node -> val != in[inStart]) {
            inStart++;
        }
        node->left = build(in, x, inStart - 1, po, a, a + inStart - x - 1);
        node->right = build(in, inStart + 1, y, po, a + inStart - x, b - 1);
        return node;
    }
    TreeNode* buildTree(vector<int>& in, vector<int>& po) {
        return build(in, 0, in.size() - 1, po, 0, po.size() - 1);
    }
};

