/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    map<int,int> mp;
    TreeNode* solve(vector<int> &inorder,int instart,int inend,vector<int> &postorder,int poststart,int postend)
    {
        if(instart>inend or poststart>postend)
            return nullptr;
        TreeNode* root=new TreeNode(postorder[postend]);
        int inrootpos=mp[root->val];
        int numleft=inrootpos-instart;
        root->left=solve(inorder,instart,inrootpos-1,postorder,poststart,poststart+numleft-1);
        root->right=solve(inorder,inrootpos+1,inend,postorder,poststart+numleft,postend-1);
        return root;
    }
    TreeNode* buildTree(vector<int>& inorder, vector<int>& postorder) {
        int n=inorder.size();
        for(int i=0;i<n;i++)
            mp[inorder[i]]=i;
        return solve(inorder,0,n-1,postorder,0,n-1);
    }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    TreeNode* buildTree(vector<int>& inorder, vector<int>& postorder) {
        return _buildTree(inorder, postorder, 0, inorder.size() - 1, 0, postorder.size() - 1); 
    }

    TreeNode* _buildTree(vector<int>& inorder, vector<int>& postorder,
            int in_left, int in_right, int post_left, int post_right) {
        if (in_left > in_right)
            return NULL;
        TreeNode* cur_node = new TreeNode(postorder[post_right]);
        int ind = -1;
        for (int i = in_left; i <= in_right; i++) {
            if (inorder[i] == postorder[post_right]) {
                ind = i;
                break;
            }
        }
        cur_node->left = _buildTree(inorder, postorder, in_left, ind - 1,
            post_left, post_left + ind - 1 - in_left);
        cur_node->right = _buildTree(inorder, postorder, ind + 1, in_right,
            post_left + ind - in_left, post_right - 1);
        return cur_node;
    }
};

